parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "candidate_name": {
      "type": "string",
      "description": "Full name of the candidate extracted from the resume."
    },
    "job_title": {
      "type": "string",
      "description": "Job title from the provided job description."
    },
    "candidate_summary": {
      "type": "string",
      "description": "A concise summary (2-3 sentences) describing the candidate's background, experience, and overall suitability for the role."
    },
    "matched_skills": {
      "type": "array",
      "description": "List only the skills that appear in BOTH the resume and the job description.",
      "items": {
        "type": "string"
      }
    },
    "missing_skills": {
      "type": "array",
      "description": "List skills required by the job description but missing from the candidate's resume.",
      "items": {
        "type": "string"
      }
    },
    "additional_skills": {
      "type": "array",
      "description": "Skills present in the resume that are not explicitly mentioned in the job description but may still add value.",
      "items": {
        "type": "string"
      }
    },
    "strengths": {
      "type": "array",
      "description": "List the candidate's strongest qualifications supported by evidence from the resume.",
      "items": {
        "type": "string"
      }
    },
    "weaknesses": {
      "type": "array",
      "description": "List genuine weaknesses or gaps compared to the job description. Do not invent weaknesses.",
      "items": {
        "type": "string"
      }
    },
    "experience_match": {
      "type": "string",
      "description": "Explain whether the candidate's work experience aligns with the job requirements. Mention years of experience if available."
    },
    "education_match": {
      "type": "string",
      "description": "Describe whether the candidate's education satisfies the requirements in the job description."
    },
    "risk_assessment": {
      "type": "object",
      "description": "Assessment of hiring risk based only on information available in the resume and job description.",
      "properties": {
        "risk_score": {
          "type": "string",
          "enum": [
            "Low",
            "Medium",
            "High"
          ],
          "description": "Overall hiring risk."
        },
        "reason": {
          "type": "string",
          "description": "Explain why this risk level was assigned."
        }
      },
      "required": [
        "risk_score",
        "reason"
      ]
    },
    "reward_assessment": {
      "type": "object",
      "description": "Assessment of the candidate's potential value if hired.",
      "properties": {
        "reward_score": {
          "type": "string",
          "enum": [
            "Low",
            "Medium",
            "High"
          ],
          "description": "Potential business value."
        },
        "reason": {
          "type": "string",
          "description": "Explain why this reward level was assigned."
        }
      },
      "required": [
        "reward_score",
        "reason"
      ]
    },
    "overall_fit_rating": {
      "type": "integer",
      "minimum": 0,
      "maximum": 10,
      "description": "Overall fit between candidate and job on a scale from 0 to 10."
    },
    "ats_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Overall ATS compatibility score from 0 to 100."
    },
    "recommendation": {
      "type": "string",
      "enum": [
        "Reject",
        "Consider",
        "Shortlist",
        "Strong Hire"
      ],
      "description": "Final hiring recommendation."
    },
    "interview_questions": {
      "type": "array",
      "description": "Generate 5 interview questions based only on the candidate's skills, experience, and any identified gaps.",
      "items": {
        "type": "string"
      }
    },
    "justification": {
      "type": "string",
      "description": "Provide a detailed explanation for the ATS score and recommendation using only evidence from the resume and job description. Do not make assumptions."
    }
  },
  "required": [
    "candidate_name",
    "job_title",
    "candidate_summary",
    "matched_skills",
    "missing_skills",
    "additional_skills",
    "strengths",
    "weaknesses",
    "experience_match",
    "education_match",
    "risk_assessment",
    "reward_assessment",
    "overall_fit_rating",
    "ats_score",
    "recommendation",
    "interview_questions",
    "justification"
  ]
}
